import { spawn } from 'node:child_process';
import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import net from 'node:net';

const ROOT = dirname(fileURLToPath(import.meta.url));
const dir = mkdtempSync(join(tmpdir(), 'fh-verify-'));
const child = spawn(process.execPath, [join(ROOT, 'server.ts'), 'serve', '--host', '127.0.0.1', '--port', '0', '--data-dir', dir], { cwd: ROOT, stdio: ['ignore', 'pipe', 'pipe'] });

const origin = await new Promise((resolve, reject) => {
  let buf = '';
  child.stdout.on('data', (c) => {
    buf += c;
    const m = buf.match(/listening on (http:\/\/\S+)/);
    if (m) resolve(new URL(m[1]));
  });
  child.on('exit', (code) => reject(new Error('server exited ' + code)));
  setTimeout(() => reject(new Error('startup timeout')), 5000);
});

let failures = 0;
function check(name, cond, extra = '') {
  if (cond) console.log('PASS', name);
  else { failures++; console.log('FAIL', name, extra); }
}

// 用最原始的 TCP 发送，精确控制：是否声明 Content-Length、分段节奏、发完后保持连接等待。
function rawRequest({ headers, body, chunks, dripMs, host, port }) {
  return new Promise((resolve, reject) => {
    const sock = net.connect({ host, port });
    let received = Buffer.alloc(0);
    let settled = false;
    const done = (err, value) => { if (!settled) { settled = true; sock.destroy(); err ? reject(err) : resolve(value); } };
    sock.on('data', (d) => { received = Buffer.concat([received, d]); });
    sock.on('error', (e) => done(e));
    sock.on('close', (hadError) => {
      // 只要在关闭前读到完整响应即可；连接是否保持复用不影响判定
      done(hadError && received.length === 0 ? new Error('connection reset with no response') : null, {
        raw: received.toString('utf8'),
        parse() {
          const idx = received.indexOf('\r\n\r\n');
          if (idx < 0) throw new Error('no header terminator');
          const head = received.subarray(0, idx).toString('utf8');
          const bodyBuf = received.subarray(idx + 4);
          const status = Number(head.split('\r\n')[0].split(' ')[1]);
          const declaredLen = /content-length: (\d+)/i.exec(head)?.[1];
          return {
            status,
            complete: declaredLen !== undefined && bodyBuf.length >= Number(declaredLen),
            json: JSON.parse(bodyBuf.toString('utf8')),
          };
        },
      });
    });
    sock.on('connect', () => {
      const head = `POST /api/ideas HTTP/1.1\r\nHost: localhost\r\n${headers}\r\n`;
      sock.write(head);
      const parts = chunks ?? [body];
      let i = 0;
      const sendNext = () => {
        if (i >= parts.length) { sock.end(); return; }
        sock.write(parts[i++]);
        dripMs ? setTimeout(sendNext, dripMs) : setImmediate(sendNext);
      };
      sendNext();
    });
    setTimeout(() => done(new Error('timeout')), 15000);
  });
}

const HOST = origin.hostname;
const PORT = Number(origin.port);

// 构造合法 JSON：通过增减填充把“整段请求体”精确凑到目标字节数。
function makeJsonOfExactBytes(targetBytes) {
  const prefix = '{"title":"大小边界标题","description":"';
  const suffix = '"}';
  const fillBytes = targetBytes - Buffer.byteLength(prefix) - Buffer.byteLength(suffix);
  if (fillBytes < 0) throw new Error('target too small');
  const fill = '中'.repeat(Math.ceil(fillBytes / 3)).slice(0, Math.ceil(fillBytes / 3));
  // '中' = 3 字节；用单字节 'a' 补齐模 3
  const threeByte = Math.floor(fillBytes / 3);
  const rest = fillBytes - threeByte * 3;
  const json = prefix + '中'.repeat(threeByte) + 'a'.repeat(rest) + suffix;
  if (Buffer.byteLength(json) !== targetBytes) throw new Error('size mismatch ' + Buffer.byteLength(json));
  JSON.parse(json); // 自查合法
  return json;
}

// 1. 恰好 1,000,000 字节的合法 JSON -> 201
{
  const body = Buffer.from(makeJsonOfExactBytes(1_000_000), 'utf8');
  const r = await rawRequest({ host: HOST, port: PORT, headers: `content-length: ${body.length}\r\ncontent-type: application/json\r\nconnection: close\r\n`, chunks: [body] });
  const parsed = r.parse();
  check('恰好 1,000,000 字节：201', parsed.status === 201, r.raw.slice(0, 200));
  check('恰好 1,000,000 字节：响应完整', parsed.complete);
  check('恰好 1,000,000 字节：含保存的 idea', !!parsed.json.idea);
}

// 2. 1,000,001 字节（声明长度，一次性发送）-> 完整 400
{
  const body = Buffer.from(makeJsonOfExactBytes(1_000_000) + 'x', 'utf8');
  const r = await rawRequest({ host: HOST, port: PORT, headers: `content-length: ${body.length}\r\ncontent-type: application/json\r\nconnection: close\r\n`, chunks: [body] });
  const parsed = r.parse();
  check('1,000,001 字节(CL,单次)：400', parsed.status === 400, r.raw.slice(0, 200));
  check('1,000,001 字节(CL,单次)：响应完整', parsed.complete, r.raw);
  check('1,000,001 字节(CL,单次)：error=请求体过大 且无 idea', parsed.json.error === '请求体过大' && !parsed.json.idea, JSON.stringify(parsed.json));
}

// 3. 声明长度，分多段慢速发送，超出发生在末段
{
  const body = Buffer.from(makeJsonOfExactBytes(1_000_000) + 'xx', 'utf8');
  const chunks = [body.subarray(0, 10), body.subarray(10, 600_000), body.subarray(600_000, 999_999), body.subarray(999_999)];
  const r = await rawRequest({ host: HOST, port: PORT, headers: `content-length: ${body.length}\r\ncontent-type: application/json\r\nconnection: close\r\n`, chunks, dripMs: 5 });
  const parsed = r.parse();
  check('CL 分段慢速(末段超限)：400 完整', parsed.status === 400 && parsed.complete, r.raw.slice(0, 200));
  check('CL 分段慢速(末段超限)：请求体过大', parsed.json.error === '请求体过大' && !parsed.json.idea);
}

// 4. 未预先声明长度：chunked 传输，超出发生在中途
{
  const body = Buffer.from(makeJsonOfExactBytes(1_500_000), 'utf8');
  const chunked = [];
  for (let off = 0; off < body.length; off += 400_000) {
    const piece = body.subarray(off, Math.min(off + 400_000, body.length));
    chunked.push(Buffer.from(`${piece.length.toString(16)}\r\n`, 'ascii'), piece, Buffer.from('\r\n', 'ascii'));
  }
  chunked.push(Buffer.from('0\r\n\r\n', 'ascii'));
  const r = await rawRequest({ host: HOST, port: PORT, headers: `transfer-encoding: chunked\r\ncontent-type: application/json\r\nconnection: close\r\n`, chunks: chunked, dripMs: 5 });
  const parsed = r.parse();
  check('chunked(中途超限)：400 完整', parsed.status === 400 && parsed.complete, r.raw.slice(0, 200));
  check('chunked(中途超限)：请求体过大', parsed.json.error === '请求体过大' && !parsed.json.idea);
}

// 5. 超限且不是合法 JSON：理由仍是请求体过大
{
  const body = Buffer.from('{这根本不是json,,,,,'.padEnd(1_000_050, 'z'), 'utf8');
  const r = await rawRequest({ host: HOST, port: PORT, headers: `content-length: ${body.length}\r\ncontent-type: application/json\r\nconnection: close\r\n`, chunks: [body] });
  const parsed = r.parse();
  check('超限且非法JSON：仍为请求体过大', parsed.status === 400 && parsed.json.error === '请求体过大' && !parsed.json.idea, JSON.stringify(parsed.json));
}

// 6. Content-Length 谎报为更大的值（声明即超限），实际只发少量字节也正常结束 -> 仍 400
{
  const body = Buffer.from('{}', 'utf8');
  const r = await rawRequest({ host: HOST, port: PORT, headers: `content-length: 5_000_000\r\ncontent-type: application/json\r\nconnection: close\r\n`, chunks: [body] });
  const parsed = r.parse();
  check('声明超限但实际字节少：按声明拒绝 400', parsed.status === 400 && parsed.json.error === '请求体过大', JSON.stringify(parsed.json));
}

// 7. 未超限的非法 JSON 仍是原有错误
{
  const body = Buffer.from('not json at all', 'utf8');
  const r = await rawRequest({ host: HOST, port: PORT, headers: `content-length: ${body.length}\r\ncontent-type: application/json\r\nconnection: close\r\n`, chunks: [body] });
  const parsed = r.parse();
  check('限制内非法JSON：原有错误', parsed.status === 400 && parsed.json.error === '请求体不是有效的 JSON', JSON.stringify(parsed.json));
}

// 8. 拒绝后列表状态：被拒意见不入库；之后正常提交成功并排最前
{
  const list0 = await (await fetch(`${origin.origin}api/ideas`)).json();
  const big = Buffer.from(makeJsonOfExactBytes(1_000_001), 'utf8');
  const rej = await fetch(`${origin.origin}api/ideas`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: big });
  check('fetch 超大请求不变成网络错误：status 400', rej.status === 400);
  const rejJson = await rej.json();
