const ROOT = dirname(fileURLToPath(import.meta.url));
const dir = mkdtempSync(join(tmpdir(), 'fh-verify-'));
const child = spawn(process.execPath, [join(ROOT, 'server.ts'), 'serve', '--host', '127.0.0.1', '--port', '0', '--data-dir', dir], { cwd: ROOT, stdio: ['ignore', 'pipe', 'pipe'] });

const origin = await new Promise((resolve, reject) => {
  let buf = '';
