      const parts = chunks ?? [body];
      let i = 0;
      const sendNext = () => {
        if (i >= parts.length) { sock.end(); return; }
        sock.write(parts[i++]);
        dripMs ? setTimeout(sendNext, dripMs) : setImmediate(sendNext);
      };
      sendNext();
    });
    setTimeout(() => done(new Error('timeout')), 15000);
  });
