function makeJsonOfExactBytes(targetBytes) {
  const prefix = '{"title":"大小边界标题","description":"';
  const suffix = '"}';
  const fillBytes = targetBytes - Buffer.byteLength(prefix) - Buffer.byteLength(suffix);
  if (fillBytes < 0) throw new Error('target too small');
  const fill = '中'.repeat(Math.ceil(fillBytes / 3)).slice(0, Math.ceil(fillBytes / 3));
  // '中' = 3 字节；用单字节 'a' 补齐模 3
  const threeByte = Math.floor(fillBytes / 3);
  const rest = fillBytes - threeByte * 3;
  const json = prefix + '中'.repeat(threeByte) + 'a'.repeat(rest) + suffix;
  if (Buffer.byteLength(json) !== targetBytes) throw new Error('size mismatch ' + Buffer.byteLength(json));
  JSON.parse(json); // 自查合法
  return json;
}

